    withLayers(
      document,
      mapLayer(document.layers, id, (layer) => {
        assertUnlocked(layer, 'position', 'Moving layer');
        return { ...layer, transform: { ...layer.transform, e: x, f: y } };
      }),
      `Layer not found: ${id}`,
