  if (layer.kind === 'shape') return { width: layer.geometry.width, height: layer.geometry.height };
  if (layer.kind === 'smart-object') return { ...layer.source.canvas };
  if (layer.kind === 'adjustment' || layer.kind === 'group') return { ...canvas };
