  multiplyLayerTransforms,
  type ImageDocument,
  type Layer,
  type LayerTransform,
  type PathCommand,
  type RgbaColor,
  type ShapeGeometry,
} from '@freetoshop/core-document';
import {
  rotateTransformFromPointers,
  scaleTransformFromHandle,
  translateTransformFromPointers,
