    );
    expect(() => resizeImage({ width: 20_000, height: 10_000, method: 'bilinear' })).toThrow(
      'Image area cannot exceed 100000000 pixels',
    );
    expect(() => resizeImage({ width: 1, height: 1, method: 'cubic' as 'nearest' })).toThrow(
