describe('DirtyRegionAccumulator', () => {
  it('clips, merges touching invalidations, and consumes them atomically', () => {
    const dirty = new DirtyRegionAccumulator(100, 80);
    dirty.add({ x: -10, y: 5, width: 20, height: 10 });
    dirty.add({ x: 10, y: 5, width: 5, height: 10 });
    dirty.add({ x: 70, y: 70, width: 50, height: 50 });
    expect(dirty.peek()).toEqual([
      { x: 0, y: 5, width: 15, height: 10 },
      { x: 70, y: 70, width: 30, height: 10 },
    ]);
    expect(dirty.consume()).toHaveLength(2);
    expect(dirty.size).toBe(0);
  });

  it('collapses fragmentation and supports full invalidation', () => {
    const dirty = new DirtyRegionAccumulator(20, 10, 2);
    dirty.add({ x: 0, y: 0, width: 1, height: 1 });
    dirty.add({ x: 5, y: 0, width: 1, height: 1 });
    dirty.add({ x: 10, y: 0, width: 1, height: 1 });
    expect(dirty.peek()).toEqual([{ x: 0, y: 0, width: 11, height: 1 }]);
    dirty.invalidateAll();
    expect(dirty.consume()).toEqual([{ x: 0, y: 0, width: 20, height: 10 }]);
  });
});

import { expect, test } from '@playwright/test';
import { readFile } from 'node:fs/promises';

async function makePng(
  page: import('@playwright/test').Page,
  color: readonly [number, number, number, number],
) {
  const bytes = await page.evaluate(async (rgba) => {
    const canvas = document.createElement('canvas');
    canvas.width = 32;
    canvas.height = 32;
    const context = canvas.getContext('2d');
    if (!context) throw new Error('Canvas unavailable');
    const pixels = new Uint8ClampedArray(32 * 32 * 4);
    for (let offset = 0; offset < pixels.length; offset += 4) {
      pixels.set(rgba, offset);
    }
    context.putImageData(new ImageData(pixels, 32, 32), 0, 0);
    const blob = await new Promise<Blob>((resolve, reject) =>
      canvas.toBlob(
        (value) => (value ? resolve(value) : reject(new Error('PNG failed'))),
        'image/png',
      ),
    );
    return [...new Uint8Array(await blob.arrayBuffer())];
  }, color);
  return Buffer.from(bytes);
}

async function makeQuadrantPng(page: import('@playwright/test').Page) {
  const bytes = await page.evaluate(async () => {
    const canvas = document.createElement('canvas');
    canvas.width = 32;
    canvas.height = 32;
    const context = canvas.getContext('2d');
    if (!context) throw new Error('Canvas unavailable');
    for (const [color, x, y] of [
      ['rgb(200, 0, 0)', 0, 0],
      ['rgb(0, 180, 0)', 16, 0],
      ['rgb(0, 0, 220)', 0, 16],
      ['rgb(220, 180, 0)', 16, 16],
    ] as const) {
      context.fillStyle = color;
      context.fillRect(x, y, 16, 16);
    }
    const blob = await new Promise<Blob>((resolve, reject) =>
      canvas.toBlob(
        (value) => (value ? resolve(value) : reject(new Error('PNG failed'))),
        'image/png',
      ),
    );
    return [...new Uint8Array(await blob.arrayBuffer())];
  });
  return Buffer.from(bytes);
}

async function documentPoint(page: import('@playwright/test').Page, x: number, y: number) {
  const canvas = page.locator('canvas[aria-label$=" canvas"]');
  const box = await canvas.boundingBox();
  if (!box) throw new Error('Canvas bounds unavailable');
  const zoom = Math.min((box.width - 72) / 32, (box.height - 72) / 32);
  const panX = (box.width - 32 * zoom) / 2;
  const panY = (box.height - 32 * zoom) / 2;
  return { x: box.x + panX + (x + 0.5) * zoom, y: box.y + panY + (y + 0.5) * zoom };
}

async function documentCoordinate(page: import('@playwright/test').Page, x: number, y: number) {
  const canvas = page.locator('canvas[aria-label$=" canvas"]');
  const box = await canvas.boundingBox();
  if (!box) throw new Error('Canvas bounds unavailable');
