    const brush: BrushOptions = { ...redBrush, size: 24, hardness: 0.85, opacity: 0.9 };
    // Simulate one frame of pointer samples along a short diagonal.
    const points = Array.from({ length: 12 }, (_, index) => ({
      x: 200 + index * 3,
      y: 180 + index * 2,
