    // Sparse result may allocate one tile (≤ dest canvas) but not more than dense full buffer.
    expect(sparseResult.allocatedByteLength).toBeLessThanOrEqual(32 * 32);
    expect(sparseResult.tileCount).toBeGreaterThan(0);
