          throw new DocumentInvariantError(`Layer is not a pixel layer: ${id}`);
        assertUnlocked(layer, 'pixels', 'Replacing pixels');
        if (ownedPixels.length !== layer.width * layer.height * 4) {
          throw new DocumentInvariantError(
