  destinationWidth: number,
  destinationHeight: number,
  method: ResamplingMethod,
): TiledPixelStore {
  validateOutputSize(store.width, store.height, 'Source image');
  validateOutputSize(destinationWidth, destinationHeight, 'Destination image');
