  return new Promise((resolve, reject) => {
    transaction.oncomplete = () => resolve();
    transaction.onerror = () =>
      reject(new PersistenceError(`Could not ${operation}`, { cause: transaction.error }));
    transaction.onabort = () =>
      reject(new PersistenceError(`Could not ${operation}`, { cause: transaction.error }));
  });
}

